use aes::cipher::{block_padding::Pkcs7, BlockDecryptMut, KeyIvInit};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

type HmacSha256 = Hmac<Sha256>;
type Aes256CbcDec = cbc::Decryptor<aes::Aes256>;

#[derive(Debug, Clone, PartialEq)]
pub enum ProcessError {
    AuthenticationFailed,
    MalformedMessage,
}

/// Message format: [IV (16 bytes)] [Ciphertext (N bytes, block-aligned)] [HMAC-SHA256 (32 bytes)]
/// Security: Encrypt-then-MAC with HMAC-SHA256 verification before decryption
pub struct SecureProcessor {
    encryption_key: [u8; 32],
    mac_key: [u8; 32],
    rate_limiter: Arc<Mutex<RateLimiter>>,
}

struct RateLimiter {
    attempts: Vec<Instant>,
    max_per_window: usize,
    window: Duration,
}

impl RateLimiter {
    fn new(max_per_window: usize, window: Duration) -> Self {
        Self {
            attempts: Vec::new(),
            max_per_window,
            window,
        }
    }

    fn check_rate_limit(&mut self) -> bool {
        let now = Instant::now();
        self.attempts.retain(|t| now.duration_since(*t) < self.window);
        if self.attempts.len() >= self.max_per_window {
            return false;
        }
        self.attempts.push(now);
        true
    }
}

impl SecureProcessor {
    pub fn new(encryption_key: [u8; 32], mac_key: [u8; 32]) -> Self {
        Self {
            encryption_key,
            mac_key,
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(100, Duration::from_secs(60)))),
        }
    }

    /// Verify HMAC-SHA256 over the authenticated portion of the message.
    /// This MUST be called before any decryption to prevent oracle attacks.
    fn verify_mac(&self, message: &[u8]) -> Result<(), ProcessError> {
        if message.len() < 64 {
            return Err(ProcessError::MalformedMessage);
        }

        let mac_offset = message.len() - 32;
        let authenticated_data = &message[16..mac_offset]; // ciphertext only
        let received_mac = &message[mac_offset..];

        let mut mac = HmacSha256::new_from_slice(&self.mac_key)
            .map_err(|_| ProcessError::AuthenticationFailed)?;
        mac.update(authenticated_data);
        mac.verify_slice(received_mac)
            .map_err(|_| ProcessError::AuthenticationFailed)?;

        Ok(())
    }

    /// Decrypt the payload after MAC verification has passed.
    /// Returns plaintext or a generic error (no padding oracle leakage).
    fn decrypt_payload(&self, message: &[u8]) -> Result<Vec<u8>, ProcessError> {
        let mac_offset = message.len() - 32;
        let (iv_and_ct, _mac) = message.split_at(mac_offset);
        let (iv_bytes, ciphertext) = iv_and_ct.split_at(16);

        if ciphertext.is_empty() || ciphertext.len() % 16 != 0 {
            return Err(ProcessError::AuthenticationFailed);
        }

        let iv: [u8; 16] = iv_bytes.try_into()
            .map_err(|_| ProcessError::AuthenticationFailed)?;

        let mut buffer = ciphertext.to_vec();
        let decryptor = Aes256CbcDec::new(&self.encryption_key.into(), &iv.into());

        match decryptor.decrypt_padded_mut::<Pkcs7>(&mut buffer) {
            Ok(plaintext) => Ok(plaintext.to_vec()),
            Err(_) => Err(ProcessError::AuthenticationFailed),
        }
    }

    /// Process an incoming encrypted message.
    /// 1. Rate limiting check
    /// 2. MAC verification (constant-time)
    /// 3. Decryption only if MAC passes
    pub fn process_message(&self, encrypted_msg: &[u8]) -> Result<Vec<u8>, ProcessError> {
        // Rate limiting to prevent brute-force
        {
            let mut limiter = self.rate_limiter.lock()
                .map_err(|_| ProcessError::AuthenticationFailed)?;
            if !limiter.check_rate_limit() {
                return Err(ProcessError::AuthenticationFailed);
            }
        }

        // Step 1: Verify MAC BEFORE any decryption (Encrypt-then-MAC)
        self.verify_mac(encrypted_msg)?;

        // Step 2: Only decrypt if MAC verification passed
        self.decrypt_payload(encrypted_msg)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rejects_tampered_ciphertext() {
        let proc = SecureProcessor::new([0x42; 32], [0x13; 32]);
        let fake_msg = vec![0u8; 80]; // random bytes won't pass MAC
        assert_eq!(proc.process_message(&fake_msg), Err(ProcessError::AuthenticationFailed));
    }

    #[test]
    fn test_rejects_short_message() {
        let proc = SecureProcessor::new([0x42; 32], [0x13; 32]);
        let short_msg = vec![0u8; 32];
        assert_eq!(proc.process_message(&short_msg), Err(ProcessError::MalformedMessage));
    }
}
